use std::fmt::Write as _;

use super::native_dynamic_package_plan::{
    append_native_dynamic_abi_contract_toml, NativeDynamicPackageExportPlan,
};

pub(super) fn native_plugin_load_manifest_template(
    packages: &[NativeDynamicPackageExportPlan],
) -> String {
    let mut output = String::from(
        "# Generated by Zircon export. Native dynamic plugins are loaded from these packages.\n",
    );
    for package in packages {
        let package_report = format!("{}/native_dynamic_package.toml", package.path);
        writeln!(
            output,
            "\n[[plugins]]\nid = {:?}\npath = {:?}\nmanifest = {:?}\npackage_report = {:?}",
            package.package_id, package.path, package.manifest, package_report
        )
        .expect("writing native plugin load manifest to String cannot fail");
        append_native_dynamic_abi_contract_toml(&mut output, "plugins.abi", &package.abi);
    }
    output
}

#[cfg(test)]
mod tests {
    use super::{native_plugin_load_manifest_template, NativeDynamicPackageExportPlan};

    #[test]
    fn streaming_load_manifest_preserves_toml_contract() {
        let package = NativeDynamicPackageExportPlan::for_package_id("sound");

        assert_eq!(
            native_plugin_load_manifest_template(&[package]),
            concat!(
                "# Generated by Zircon export. Native dynamic plugins are loaded from these packages.\n",
                "\n[[plugins]]\n",
                "id = \"sound\"\n",
                "path = \"plugins/sound\"\n",
                "manifest = \"plugins/sound/plugin.toml\"\n",
                "package_report = \"plugins/sound/native_dynamic_package.toml\"\n",
                "\n[plugins.abi]\n",
                "abi_version = 3\n",
                "descriptor_symbol = \"zircon_native_plugin_descriptor_v3\"\n",
                "descriptor_contract = \"NativePluginAbiV3\"\n",
                "runtime_entry_source = \"NativePluginAbiV3.runtime_entry_name\"\n",
                "editor_entry_source = \"NativePluginAbiV3.editor_entry_name\"\n",
                "host_function_table = \"NativePluginHostFunctionTableV3\"\n",
                "entry_report_contract = \"NativePluginEntryReportV3\"\n",
                "behavior_contract = \"NativePluginBehaviorV4\"\n",
                "state_snapshot_contract = \"NativePluginBehaviorV4.save_state/restore_state\"\n",
                "bridge_method_table = \"NativePluginBridgeMethodTableV3\"\n",
            )
        );
    }
}
